public class Element_nextElementSibling_TriageGen2Test {

    private Element parentElement;
    private Element childElement1;
    private Element childElement2;
    private Element childElement3;

    @Before
    public void setUp() {
        parentElement = new Element(Tag.valueOf("div"), null);
        childElement1 = new Element(Tag.valueOf("p"), null);
        childElement2 = new Element(Tag.valueOf("span"), null);
        childElement3 = new Element(Tag.valueOf("a"), null);

        parentElement.appendChild(childElement1);
        parentElement.appendChild(childElement2);
        parentElement.appendChild(childElement3);
    }

    @Test
    public void testNextElementSibling_Exists() {
        Element nextSibling = childElement1.nextElementSibling();
        assertEquals(childElement2, nextSibling);
    }














}

