import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class Element_nextElementSibling_TriageGen2Test {

    private Element parentElement;
    private Element childElement1;
    private Element childElement2;
    private Element childElement3;

    @Before
    public void setUp() {
        parentElement = new Element(Tag.valueOf("div"), null);
        childElement1 = new Element(Tag.valueOf("p"), null);
        childElement2 = new Element(Tag.valueOf("span"), null);
        childElement3 = new Element(Tag.valueOf("a"), null);

        parentElement.appendChild(childElement1);
        parentElement.appendChild(childElement2);
        parentElement.appendChild(childElement3);
    }













    @Test
    public void testNextElementSibling_SiblingsFromJSDom() {
        String html = "<div><p>1</p><span>2</span><a>3</a></div>";
        Element root = Jsoup.parse(html).body();
        Element firstChild = root.child(0);
        Element secondChild = root.child(1);
        Element thirdChild = root.child(2);

        assertEquals(secondChild, firstChild.nextElementSibling());
        assertEquals(thirdChild, secondChild.nextElementSibling());
        assertNull(thirdChild.nextElementSibling());
    }


}
